{
  "name": "Apex Bank - Account Balance Flow",
  "nodes": [
    {
      "client_id": "welcome",
      "type": "play",
      "is_start": true,
      "prompt_id": "{{prompt_welcome_audio}}",
      "next": "menu"
    },
    {
      "client_id": "menu",
      "type": "menu",
      "prompt_text": "Press 1 to check your account balance. Press 9 to end this call.",
      "config": { "digit_timeout_ms": 8000 },
      "branches": { "1": "collect_account", "9": "hangup_node" }
    },
    {
      "client_id": "collect_account",
      "type": "collect_input",
      "prompt_text": "Please enter your ten digit account number, then press the pound key.",
      "config": { "max_digits": 10, "min_digits": 10, "terminator": "#", "store_as": "provider_number" },
      "next": "lookup_account"
    },
    {
      "client_id": "lookup_account",
      "type": "lookup",
      "config": { "source_type": "table", "table_id": "{{lookup_table_id}}", "lookup_key": "provider_number", "response_var_prefix": "provider_" },
      "branches": { "found": "speak_result", "not_found": "not_found_node" }
    },
    {
      "client_id": "speak_result",
      "type": "play",
      "prompt_text": "Thank you. Your account is registered to {{provider_name}}. Goodbye.",
      "next": "hangup_node"
    },
    {
      "client_id": "not_found_node",
      "type": "play",
      "prompt_text": "Sorry, we could not find that account number in our records.",
      "next": "hangup_node"
    },
    {
      "client_id": "hangup_node",
      "type": "hangup"
    }
  ]
}

{
  "name": "Swift Loans - Recovery Flow",
  "nodes": [
    {
      "client_id": "welcome",
      "type": "play",
      "is_start": true,
      "prompt_text": "This is Swift Loan Recovery calling about your overdue payment. Press 1 to speak with an agent, or 9 to end this call.",
      "next": "hangup_node"
    },
    {
      "client_id": "hangup_node",
      "type": "hangup"
    }
  ]
}

